    return 0;
}

int resolve_last_component(struct nameidata *nd, struct path *path) {
    struct dentry *dentry;
    int error;

    if (nd->flags & LOOKUP_RCU) {
        dentry = lookup_dcache_lock(nd->path.dentry, nd);
        if (IS_ERR(dentry))
            return PTR_ERR(dentry);

        path->dentry = dentry;
        path->mnt = nd->path.mnt;
        return 0;
    }

    dentry = d_lookup(nd->path.dentry, &nd->last);
    if (!dentry) {
        dentry = d_alloc_name(nd->path.dentry, nd->last.name);
        if (!dentry)
            return -ENOMEM;

        error = vfs_lookup(nd->path.dentry->d_inode, dentry, nd);
        if (error)
            return error;

        d_add(dentry, NULL);
    }

    path->dentry = dentry;
    path->mnt = nd->path.mnt;

    return 0;
}

int resolve_last_component(struct nameidata *nd, struct path *path) {
    struct dentry *dentry;

    if (nd->depth) {
        if (nd->flags & LOOKUP_RCU) {
            nd->flags &= ~LOOKUP_RCU;
            path_put(&nd->path);
            path_get(&nd->path);
        }

        dentry = lookup_last(nd);
        if (IS_ERR(dentry))
            return PTR_ERR(dentry);

        nd->dentry = dentry;
    } else {
        if (nd->flags & LOOKUP_RCU) {
            dentry = lookup_dcache_last(nd);
            if (IS_ERR(dentry))
                return PTR_ERR(dentry);

            if (dentry) {
                path->dentry = dentry;
                path->mnt = nd->path.mnt;
                return 0;
            }
        }

        dentry = lookup_last(nd);
        if (IS_ERR(dentry))
            return PTR_ERR(dentry);

        if (!dentry)
            return -ENOENT;

        mutex_lock(&nd->path.mnt->mnt_mutex);
        dentry = __lookup_dentry(nd->path.dentry, nd->last.name, nd->last.len);
        if (IS_ERR(dentry)) {
            mutex_unlock(&nd->path.mnt->mnt_mutex);
            return PTR_ERR(dentry);
        }

        if (!dentry) {
            mutex_unlock(&nd->path.mnt->mnt_mutex);
            return -ENOENT;
        }

        path->dentry = dentry;
        path->mnt = nd->path.mnt;
        mutex_unlock(&nd->path.mnt->mnt_mutex);
    }

    path_get(path);
    path_put(&nd->path);
    nd->path = *path;
    return 0;
}

int resolve_last_component(struct nameidata *nd, struct path *path) {
    int error;

    if (nd->flags & LOOKUP_RCU) {
        struct dentry *dentry = lookup_dcache_lock(nd, path);
        if (IS_ERR(dentry))
            return PTR_ERR(dentry);
        path->dentry = dentry;
        return 0;
    }

    error = path_lookup_last_common(nd, path);
    if (error)
        return error;

    if (unlikely(!path->dentry->d_inode)) {
        error = -ENOENT;
        goto out;
    }

    if (unlikely(S_ISLNK(path->dentry->d_inode->i_mode))) {
        error = follow_link(path->dentry, nd);
        if (error)
            goto out;
    }

    return 0;

out:
    path_put(path);
    return error;
}
